#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
MiniCut update patch 23: BUG FIXES + ICON FONT + NEW UI
=======================================================
Install AFTER apply_22_timeline_editing.py.

Bugs fixed
  1. Roll edit (drag the border of two touching clips) works only when NO clip is selected. With a clip selected, its edge
     changes that clip alone (it can never overlap the neighbour), so a clip at the end of its footage no longer blocks you.
  2. Copy / paste in the same place (and Duplicate) never lands on top of another clip: it goes to a free track, or a new one.
  3. Compound clips show their waveform (with the volume line) and have "Extract audio" (nested compounds included).
  4. Uniform scale remembers the X:Y ratio, so it keeps working when one side is 0 and when you drag it back up from 0.
  5. Export runs in the background, several at once (default 2 at a time, the rest wait), and EVERY export can be cancelled
     on its own (tasks window: click the progress ring or the tasks icon). Cancelling stops the encoder and deletes the
     half-written file. Closing the export window or editing the project no longer affects a running export.

Look and speed
  * Icons: Google Material Icons as an icon FONT, installed once in fonts/ (https://fonts.google.com/icons). No more svg/ files
    (the folder is only a fallback). Any Material name can be used: app_icon("content_cut").
  * Nodes are pastel in their category colour, the same colour as the block in the list.
  * Node page: the splitters are visible and grabbable, so the preview can be resized in height as well as width.
  * Mask: the mouse wheel zooms the picture in EVERY mode (Ctrl + wheel resizes the mask); zoom buttons; right-drag pans.
  * UI re-organised to be icon-first: top bar, panels, inspector tabs and rows, track header, toolbars, node page, export window.

Changed files: app.py, shared/{theme,core,widgets,icons,tasks}.py, workspace/{timeline_ops,actions,progress_ring,node_editor,panels,timeline}.py,
render/export.py.  New: fonts/MaterialIconsOutlined-Regular.otf  (originals are backed up first)

    python apply_23_icons_ui_bugfix.py            install the update
    python apply_23_icons_ui_bugfix.py --check    only show what would change
    python apply_23_icons_ui_bugfix.py --revert   undo the last install
    python apply_23_icons_ui_bugfix.py --force    install even if you edited one of these files yourself
"""

import base64, datetime, hashlib, json, os, py_compile, shutil, subprocess, sys, zlib

EDITS = {}
NEW_FILES = {}
