                                            '    def set_shape(self, n):\n'
                                            '        self.edit(lambda ms, c: c.__setitem__("mask", n)); self._update_ui(n)\n'
                                            '    def reset(self):\n'
                                            '        self.edit(lambda ms, c: (ms.clear(), ms.update(copy.deepcopy(MASK_DEFAULT)), '
                                            'c.__setitem__("mask_feather", 0)))\n'
                                            '    def _update_ui(self, sh):\n'
                                            '        for n, b in self.btns.items(): b.setChecked(n == sh)\n'
                                            '        par = sh not in ("None", "Custom")\n'
                                            '        vis = {"cx": par, "cy": par, "w": sh in ("Circle", "Rect", "Heart", "Star"),\n'
                                            '               "h": sh in ("Circle", "Rect", "Heart", "Star", "Filmstrip"), "rot": par,\n'
                                            '               "round": sh == "Rect", "feather": sh != "None"}\n'
                                            '        for k, (s, sc, val, l) in self.sl.items():\n'
                                            '            for w in (s, val, l): w.setVisible(vis[k])\n'
                                            '        self.inv.setVisible(sh != "None")\n'
                                            '        self.hint.setText("คลิก = เพิ่มจุด • ลากจุด = ย้าย • คลิกขวาที่จุด = ลบ • ล้อเมาส์ = ซูม • '
                                            'ลากด้วยปุ่มกลาง = เลื่อนภาพ" if sh == "Custom"\n'
                                            '                          else "" if sh == "None" else "ลากเพื่อย้ายมาสก์ • ล้อเมาส์ = ซูมภาพ • '
                                            'Ctrl+ล้อ = ย่อ/ขยายมาสก์ • คลิกขวาลาก = เลื่อนภาพ")\n'
