                                            '    def load(self, c, force=False):\n'
                                            '        h = self._h(c); key = (c["id"] if c else None, id(h))\n'
                                            '        if key == self.cid and not force: return\n'
                                            '        self.cid = key\n'
                                            '        if c and h is not None: self._sync_sliders(h); self._grab_bg(c)\n'
                                            '        self._update_ui(self.shape())\n'
                                            '        self._refresh_layers(); self._refresh_images()\n'
                                            '    def follow(self, t):\n'
                                            '        """The playhead moved: show the picture under the playhead in the mask editor (about every 50 '
                                            'ms at most)."""\n'
                                            '        c = self.app.sel_clip()\n'
                                            '        if not c or c["kind"] == "audio" or not self.isVisible(): return\n'
                                            '        last = getattr(self, "_bg_key", None)\n'
                                            '        if last is not None and last[0] == c["id"] and abs(last[1] - t) < 0.05: return\n'
                                            '        self._bg_key = (c["id"], t); self._grab_bg(c, t); self.canvas.update()\n'
                                            '    def _grab_bg(self, c, t=None):\n'
                                            '        t = self.app.t if t is None else t\n'
                                            '        self.canvas.bg = None; pj = self.app.proj; self.src_size = (pj.w, pj.h) if pj else (16, 9)\n'
                                            '        try:\n'
                                            '            r = self.app.renderer; src = r.pool.get(c)\n'
                                            '            if src is None: return\n'
                                            '            self.src_size = (max(1, src.w), max(1, src.h))\n'
                                            '            with getattr(r, "_src_lock", threading.RLock()):\n'
                                            '                img = src.frame(max(0.0, c["inp"] + (t - c["start"])) if c["kind"] != "image" else 0, '
                                            '.25)\n'
                                            '            if img is not None: self.canvas.bg = np_to_qimage(img)\n'
                                            '        except Exception as ex: print("mask bg:", ex)\n'
                                            '\n'
                                            '\n'
                                            'def placeholder_icon(kind, w=112, h=64):\n'
                                            '    pm = QPixmap(w, h); pm.fill(Qt.transparent); p = QPainter(pm); '
                                            'p.setRenderHint(QPainter.Antialiasing)\n'
                                            '    p.setPen(Qt.NoPen); p.setBrush(QColor("#16213a")); p.drawRoundedRect(0, 0, w, h, 8, 8)\n'
                                            '    if kind == "audio":\n'
                                            '        p.setPen(QPen(QColor("#5aa2ff"), 2.2, Qt.SolidLine, Qt.RoundCap))\n'
                                            '        heights = [8, 14, 6, 22, 30, 15, 24, 11, 32, 18, 9, 25, 13, 29, 17, 7, 21, 12]\n'
                                            '        cx = w / 2 - len(heights) * 3 / 2\n'
                                            '        for i, hh in enumerate(heights): p.drawLine(QPointF(cx + i * 3, h / 2 - hh / 2), QPointF(cx + i '
                                            '* 3, h / 2 + hh / 2))\n'
                                            '    else:\n'
                                            '        nm = {"video": "video", "image": "image", "gif": "gif"}.get(kind)\n'
                                            '        if nm:\n'
                                            '            s = int(min(w, h) * 0.5); p.drawPixmap((w - s) // 2, (h - s) // 2, svg_pixmap(nm, '
                                            '"#5aa2ff", s))\n'
                                            '        else:\n'
                                            '            p.setPen(QColor("#5aa2ff")); f = p.font(); f.setPointSize(15); f.setBold(True); '
                                            'p.setFont(f)\n'
                                            '            p.drawText(QRect(0, 0, w, h), Qt.AlignCenter, "?")\n'
                                            '    p.end()\n'
                                            '    return QIcon(pm)\n'
                                            '\n'
                                            '\n'
                                            'def icon_from_image(img, w=112, h=64):\n'
                                            '    pm = QPixmap(w, h); pm.fill(Qt.transparent); p = QPainter(pm); '
                                            'p.setRenderHint(QPainter.Antialiasing)\n'
                                            '    path = QPainterPath(); path.addRoundedRect(0, 0, w, h, 8, 8); p.setClipPath(path); p.fillRect(0, 0, '
                                            'w, h, QColor("#05080f"))\n'
                                            '    s = min(w / img.width(), h / img.height()); iw, ih = img.width() * s, img.height() * s\n'
                                            '    p.setRenderHint(QPainter.SmoothPixmapTransform); p.drawImage(QRectF((w - iw) / 2, (h - ih) / 2, iw, '
                                            'ih), img); p.end()\n'
                                            '    return QIcon(pm)\n'
                                            '\n'
                                            '\n'
                                            'def scan_folder(folder, depth=2, limit=600):\n'
                                            '    out = []\n'
                                            '    def rec(d, lv):\n'
                                            '        try: entries = sorted(os.scandir(d), key=lambda e: e.name.lower())\n'
                                            '        except Exception: return\n'
                                            '        for e in entries:\n'
                                            '            if len(out) >= limit: return\n'
                                            '            try:\n'
                                            '                if e.is_dir(follow_symlinks=False):\n'
                                            '                    if lv < depth and not e.name.startswith("."): rec(e.path, lv + 1)\n'
                                            '                elif kind_of(e.name): out.append(e.path)\n'
                                            '            except Exception: pass\n'
                                            '    if folder and os.path.isdir(folder): rec(folder, 0)\n'
                                            '    return out\n'
                                            '\n'
                                            '\n'
                                            'class MediaList(QListWidget):\n'
                                            '    files_dropped = Signal(list)\n'
                                            '    def __init__(self):\n'
                                            '        super().__init__(); self.setViewMode(QListView.IconMode); self.setIconSize(QSize(112, 64)); '
                                            'self.setGridSize(QSize(124, 100))\n'
                                            '        self.setResizeMode(QListView.Adjust); self.setMovement(QListView.Static); '
                                            'self.setWordWrap(True)\n'
                                            '        self.setSelectionMode(QAbstractItemView.ExtendedSelection); self.setDragEnabled(True); '
                                            'self.setAcceptDrops(True)\n'
                                            '        self.setDragDropMode(QAbstractItemView.DragDrop); self.setDefaultDropAction(Qt.CopyAction); '
                                            'self.setUniformItemSizes(True)\n'
                                            '    def mimeTypes(self): return ["text/uri-list"]\n'
                                            '    def mimeData(self, items):\n'
                                            '        md = QMimeData(); md.setUrls([QUrl.fromLocalFile(i.data(Qt.UserRole)) for i in items]); return '
                                            'md\n'
                                            '    def supportedDropActions(self): return Qt.CopyAction\n'
                                            '    def dragEnterEvent(self, e):\n'
                                            '        if e.mimeData().hasUrls() and e.source() is not self: e.setDropAction(Qt.CopyAction); '
                                            'e.accept()\n'
                                            '        else: e.ignore()\n'
                                            '    def dragMoveEvent(self, e):\n'
                                            '        if e.source() is not self: e.setDropAction(Qt.CopyAction); e.accept()\n'
                                            '    def dropEvent(self, e):\n'
                                            '        if e.source() is self: return\n'
                                            '        self.files_dropped.emit([u.toLocalFile() for u in e.mimeData().urls() if u.isLocalFile()]); '
                                            'e.accept()\n'
                                            '\n'
