                                            '        f.addLayout(form); f.addStretch(); self.tabs.addTab(sa, "Text")\n'
                                            '        # Audio\n'
                                            '        sa, f = page(); r = PropRow(self, "volume", "Volume", 0, 1000, 0, 200, 0, "%"); '
                                            'self.rows["volume"] = r; f.addWidget(r); self.afx_panel = AudioFxPanel(self.app); '
                                            'f.addWidget(self.afx_panel); f.addStretch()\n'
                                            '        self.tabs.addTab(sa, "Audio")\n'
                                            '        # Keyframes: the curve on top, then what it applies to, the actions and the curve presets\n'
                                            '        sa, f = page(); self.checked = set(); self._toggle_cid = None; self._more = False; '
                                            'self._presets_key = None\n'
                                            '        self.kprop = QComboBox(); [self.kprop.addItem(lab, k) for k, lab in KEY_PROPS]; '
                                            'self.kprop.hide()\n'
                                            '        self.kprop.currentIndexChanged.connect(lambda *_: self.refresh())\n'
                                            '        self.preset = QComboBox(); self.preset.addItems(list(EASE_PRESETS) + ["Custom"]); '
                                            'self.preset.hide()\n'
                                            '        self.ease = EaseEditor(); self.ease.changed.connect(self.on_ease); '
                                            'self.ease.setMinimumHeight(200); f.addWidget(self.ease)\n'
                                            '        self.kinfo = QLabel(); self.kinfo.setObjectName("Dim"); self.kinfo.setWordWrap(True); '
                                            'f.addWidget(self.kinfo)\n'
                                            '        lab = QLabel("Applies to"); lab.setObjectName("H2"); f.addWidget(lab)\n'
                                            '        self.toggle_row = QGridLayout(); self.toggle_row.setSpacing(4); f.addLayout(self.toggle_row)\n'
                                            '        self.toggles = {}\n'
                                            '        for i, (k, name) in enumerate(KEY_PROPS):\n'
                                            '            b = QToolButton(); b.setText(name); b.setCheckable(True); '
                                            'b.setToolButtonStyle(Qt.ToolButtonTextOnly); b.setMinimumHeight(26)\n'
                                            '            b.toggled.connect(lambda v, k=k: self.on_toggle(k, v)); self.toggles[k] = b; '
                                            'self.toggle_row.addWidget(b, i // 3, i % 3)\n'
                                            '        acts = QGridLayout(); acts.setSpacing(4)\n'
                                            '        for i, (label, tip, cb) in enumerate((\n'
                                            '                ("Apply to all", "Copy the curve to every segment of the checked properties", '
                                            'self.apply_checked),\n'
                                            '                ("All segments", "Copy the curve to every segment of the current property", '
                                            'self.apply_all),\n'
                                            '                ("Clear", "Delete the keyframes of the current property", self.clear_keys),\n'
                                            '                ("Clear all", "Delete the keyframes of every property of this clip", '
                                            'self.clear_all_keys))):\n'
                                            '            b = QPushButton(label); b.setToolTip(tip); b.clicked.connect(cb); acts.addWidget(b, i // 2, '
                                            'i % 2)\n'
                                            '        f.addLayout(acts)\n'
                                            '        head = QHBoxLayout(); l2 = QLabel("Curve presets"); l2.setObjectName("H2"); head.addWidget(l2); '
                                            'head.addStretch()\n'
                                            '        save = QPushButton("Save curve"); save.setToolTip("Keep the curve shown above as a preset of '
                                            'your own"); save.clicked.connect(self._save_preset); head.addWidget(save)\n'
                                            '        self.more_btn = QPushButton("More…"); self.more_btn.clicked.connect(self._toggle_more); '
                                            'head.addWidget(self.more_btn); f.addLayout(head)\n'
                                            '        self.preset_grid = QGridLayout(); self.preset_grid.setSpacing(6); '
                                            'f.addLayout(self.preset_grid)\n'
                                            '        b1 = QPushButton("Delete key"); b1.clicked.connect(lambda: '
                                            'self.toggle_key(self.kprop.currentData(), only_remove=True))\n'
                                            '        f.addWidget(b1); f.addStretch()\n'
                                            '        self.tabs.addTab(sa, "Keyframes")\n'
                                            '    # ---- refresh ----\n'
                                            '    def _refresh_core(self, full=False):\n'
                                            '        c = self.app.sel_clip(); self.empty.setVisible(c is None); self.tabs.setVisible(c is not None)\n'
                                            '        if not c: return\n'
                                            '        self.loading = True; k = c["kind"]; vis = is_visual(k)\n'
                                            '        for i, ok in enumerate((vis, vis, k == "text", k in ("video", "audio", "compound"), True)): '
                                            'self.tabs.setTabVisible(i, ok)\n'
                                            '        lt = self.app.t - c["start"]\n'
                                            '        for n, row in self.rows.items(): row.set(prop_at(c, n, lt), key_at(c, n, lt) is not None, '
                                            'bool(c["props"][n]["k"]))\n'
                                            '        self.blend.setCurrentIndex(BLENDS.index(c["blend"]) if c["blend"] in BLENDS else 0)\n'
                                            '        self.afx_panel.setVisible(k != "compound")\n'
                                            '        self.fx_panel.load(c, force=full)\n'
                                            '        self.afx_panel.load(c, force=full)\n'
                                            '        if full:\n'
                                            '            if self.txt.toPlainText() != c["text"]: self.txt.setPlainText(c["text"])\n'
                                            '            self.font_cb.setCurrentFont(QFont(c["font"])); self.fsize.setValue(int(c["fsize"])); '
                                            'self.tcol.set(c["tcolor"])\n'
                                            '            self.bold.setChecked(bool(c["bold"])); self.stroke.setValue(int(c["stroke"])); '
                                            'self.scol.set(c["scolor"])\n'
                                            '        self._sync_toggles(c)\n'
                                            '        name = self.kprop.currentData(); ks = c["props"][name]["k"]; self._seg = None\n'
                                            '        for i in range(len(ks) - 1):\n'
                                            '            if ks[i]["t"] - 1e-6 <= lt < ks[i + 1]["t"]: self._seg = i\n'
                                            '        if self._seg is None:\n'
                                            '            self.kinfo.setText(f"{len(ks)} keyframe(s). Place the playhead between two keyframes to '
                                            'edit the motion curve."); self.ease.setEnabled(False)\n'
                                            '        else:\n'
                                            '            e = ks[self._seg]["e"]; self.kinfo.setText(f"Segment {self._seg + 1} → {self._seg + 2} of '
                                            '{len(ks)} keyframes")\n'
                                            '            self.ease.setEnabled(True); self.ease.set_e(e)\n'
                                            '            match = next((n for n, v in EASE_PRESETS.items() if [round(x, 3) for x in v] == [round(x, '
                                            '3) for x in e]), "Custom")\n'
                                            '            self.preset.setCurrentText(match)\n'
                                            '        self.loading = False\n'
                                            '    # ---- edits ----\n'
                                            '    def _c(self):\n'
                                            '        return None if self.loading else self.app.sel_clip()\n'
                                            '    def on_prop(self, name, v):\n'
                                            '        c = self._c()\n'
                                            '        if not c: return\n'
                                            '        self.app.checkpoint(("prop", c["id"], name)); lt = self.app.t - c["start"]\n'
                                            '        if name in ("sx", "sy") and self.uniform.isChecked():\n'
                                            '            # Uniform scale keeps the shape (ratio Y / X). The ratio is remembered while both sides are '
                                            'not 0, so when one\n'
                                            '            # side is 0 (or is dragged back up from 0) the other side still follows with the right '
                                            'proportion.\n'
                                            '            other = "sy" if name == "sx" else "sx"; sx0, sy0 = prop_at(c, "sx", lt), prop_at(c, "sy", '
                                            'lt)\n'
                                            '            if abs(sx0) > 1e-6 and abs(sy0) > 1e-6: self._ratio[c["id"]] = sy0 / sx0\n'
                                            '            r = self._ratio.get(c["id"], 1.0)\n'
                                            '            if abs(r) < 1e-6: r = 1.0\n'
                                            '            set_prop(c, other, lt, round(v * r if name == "sx" else v / r, 2))\n'
                                            '        set_prop(c, name, lt, v); self.app.on_changed(insp=False); self.refresh()\n'
                                            '    # ---- keyframe tab helpers: curve toggles, presets, apply / clear ----\n'
                                            '    def _curve_props(self, c):\n'
                                            '        if c is None: return []\n'
                                            '        return [k for k, _ in KEY_PROPS if (k == "volume") == (c["kind"] == "audio") and k in '
                                            'c["props"]]\n'
                                            '    def _sync_toggles(self, c):\n'
                                            '        cid = c["id"] if c else None\n'
                                            '        if getattr(self, "_toggle_cid", None) != cid: self._toggle_cid = cid; self.checked = set(); '
                                            'self._presets_key = None\n'
                                            '        avail = self._curve_props(c)\n'
