                                            'b.blockSignals(False)\n'
                                            '        key = (cid, len(self.app.settings["curve_presets"] or {}), self._more)\n'
                                            '        if self._presets_key != key: self._rebuild_presets()\n'
                                            '    def on_toggle(self, k, on):\n'
                                            '        if on: self.checked.add(k); self.kprop.setCurrentIndex(self.kprop.findData(k))\n'
                                            '        else: self.checked.discard(k)\n'
                                            '    def apply_checked(self):\n'
                                            '        c = self.app.sel_clip()\n'
                                            '        if not c: return\n'
                                            '        curve = self._curve_to_copy(); names = list(self.checked) or [self.kprop.currentData()]\n'
                                            '        targets = [kf for n in names for kf in c["props"].get(n, {}).get("k", [])[:-1]]\n'
                                            '        if not targets:\n'
                                            '            if hasattr(self.app, "toast"): self.app.toast.show_msg("Add at least 2 keyframes to the '
                                            'checked properties first")\n'
                                            '            return\n'
                                            '        self.app.checkpoint()\n'
                                            '        for kf in targets: kf["e"] = list(curve)\n'
                                            '        self.app.on_changed(insp=False); self.refresh()\n'
                                            '    def clear_all_keys(self):\n'
                                            '        c = self.app.sel_clip()\n'
                                            '        if not c: return\n'
                                            '        self.app.checkpoint(); t = self.app.t - c["start"]\n'
                                            '        for n in self._curve_props(c): c["props"][n]["v"] = prop_at(c, n, t); c["props"][n]["k"] = []\n'
                                            '        self.app.on_changed(insp=False); self.refresh()\n'
                                            '    def apply_curve(self, curve):\n'
                                            '        self.ease.set_e(curve)\n'
                                            '        if self._seg is not None: self.on_ease(curve)\n'
                                            '    def _toggle_more(self):\n'
                                            '        self._more = not self._more; self._rebuild_presets()\n'
                                            '    def _save_preset(self):\n'
                                            '        name, ok = QInputDialog.getText(self, "Save curve", "Name for this curve:")\n'
                                            '        name = (name or "").strip()\n'
                                            '        if not ok or not name: return\n'
                                            '        if not isinstance(self.app.settings["curve_presets"], dict): self.app.settings["curve_presets"] '
                                            '= {}\n'
                                            '        self.app.settings["curve_presets"][name] = [float(v) for v in self.ease.e]; '
                                            'self.app.settings.save(); self._rebuild_presets()\n'
                                            '    def _rebuild_presets(self):\n'
                                            '        c = self.app.sel_clip(); cid = c["id"] if c else None\n'
                                            '        self._presets_key = (cid, len(self.app.settings["curve_presets"] or {}), self._more)\n'
                                            '        while self.preset_grid.count():\n'
                                            '            w = self.preset_grid.takeAt(0).widget()\n'
                                            '            if w: w.deleteLater()\n'
                                            '        items = list(all_presets(self.app.settings).items())\n'
                                            '        shown = items if self._more else items[:6]\n'
                                            '        for i, (name, curve) in enumerate(shown):\n'
                                            '            tile = PresetTile(name, curve, selected=[round(v, 3) for v in curve] == [round(float(v), 3) '
                                            'for v in self.ease.e])\n'
                                            '            tile.clicked.connect(self.apply_curve); self.preset_grid.addWidget(tile, i // 3, i % 3)\n'
                                            '        self.more_btn.setText("Less" if self._more else "More…")\n'
                                            '        self.more_btn.setVisible(len(items) > 6)\n'
                                            '    def toggle_key(self, name, only_remove=False):\n'
                                            '        c = self.app.sel_clip()\n'
                                            '        if not c: return\n'
                                            '        self.app.checkpoint(); lt = self.app.t - c["start"]; k = key_at(c, name, lt)\n'
                                            '        if k: remove_key(c, name, k)\n'
                                            '        elif not only_remove: add_key(c, name, lt)\n'
                                            '        self.app.on_changed(insp=False); self.refresh()\n'
                                            '    def clear_keys(self):\n'
                                            '        c = self.app.sel_clip()\n'
                                            '        if not c: return\n'
                                            '        self.app.checkpoint(); name = self.kprop.currentData(); p = c["props"][name]\n'
                                            '        p["v"] = prop_at(c, name, self.app.t - c["start"]); p["k"] = []; '
                                            'self.app.on_changed(insp=False); self.refresh()\n'
                                            '    def jump(self, d):\n'
                                            '        c = self.app.sel_clip()\n'
                                            '        if not c: return\n'
                                            '        lt = self.app.t - c["start"]; ts = sorted({kf["t"] for pr in c["props"].values() for kf in '
                                            'pr["k"]})\n'
                                            '        nxt = [t for t in ts if t > lt + 1e-4] if d > 0 else [t for t in ts if t < lt - 1e-4]\n'
                                            '        if nxt: self.app.seek(c["start"] + (nxt[0] if d > 0 else nxt[-1]))\n'
                                            '    def on_ease(self, e):\n'
                                            '        c = self._c()\n'
                                            '        if not c or self._seg is None: return\n'
                                            '        self.app.checkpoint(("ease", c["id"])); '
                                            'c["props"][self.kprop.currentData()]["k"][self._seg]["e"] = list(e)\n'
                                            '        self.preset.setCurrentText("Custom"); self.app.on_changed(insp=False)\n'
                                            '    def on_preset(self, *_):\n'
                                            '        name = self.preset.currentText()\n'
                                            '        if name in EASE_PRESETS:\n'
                                            '            curve = EASE_PRESETS[name]\n'
                                            '            self.ease.set_e(curve)\n'
                                            '            if self._seg is not None: self.on_ease(curve)\n'
                                            '            self.preset.setCurrentText(name)\n'
                                            '    def _curve_to_copy(self):\n'
                                            '        # The curve editor is the source of truth (including a newly selected preset).\n'
                                            '        return [float(v) for v in self.ease.e]\n'
                                            '    def apply_all(self):\n'
                                            '        c = self.app.sel_clip()\n'
                                            '        if not c: return\n'
                                            '        self.app.checkpoint()\n'
                                            '        for kf in c["props"][self.kprop.currentData()]["k"]: kf["e"] = list(self.ease.e)\n'
                                            '        self.app.on_changed(insp=False)\n'
                                            '    def apply_transform_all(self):\n'
                                            '        c = self.app.sel_clip()\n'
                                            '        if not c: return\n'
                                            '        curve = self._curve_to_copy()\n'
                                            '        names = ("x", "y", "sx", "sy", "rot", "opacity")\n'
                                            '        targets = [(name, kf) for name in names for kf in c["props"].get(name, {}).get("k", [])[:-1]]\n'
                                            '        if not targets:\n'
                                            '            if hasattr(self.app, "toast"): self.app.toast.show_msg("Add at least 2 keyframes to a '
                                            'Transform property first")\n'
                                            '            return\n'
                                            '        self.app.checkpoint()\n'
                                            '        for _, kf in targets: kf["e"] = list(curve)\n'
                                            '        self.app.on_changed(insp=False); self.refresh()\n'
                                            '        if hasattr(self.app, "toast"): self.app.toast.show_msg(f"Curve applied to {len(targets)} '
                                            'Transform segments")\n'
                                            '    def on_blend(self, i):\n'
                                            '        c = self._c()\n'
                                            '        if c: self.app.checkpoint(); c["blend"] = BLENDS[i]; self.app.on_changed(insp=False)\n'
                                            '    def on_text(self, key, v):\n'
                                            '        c = self._c()\n'
                                            '        if not c or c["kind"] != "text": return\n'
                                            '        self.app.checkpoint(("text", c["id"], key)); c[key] = v\n'
                                            '        if key == "text": c["name"] = (v.split("\\n")[0] or "Text")[:40]\n'
                                            '        self.app.on_changed(insp=False)\n'
                                            '    def quick(self, what):\n'
                                            '        c = self.app.sel_clip()\n'
                                            '        if not c or not is_visual(c["kind"]): return\n'
                                            '        self.app.checkpoint(); lt = self.app.t - c["start"]; P = self.app.proj\n'
                                            '        if what == "fit": set_prop(c, "sx", lt, 100.0); set_prop(c, "sy", lt, 100.0)\n'
                                            '        elif what == "fill":\n'
                                            '            bs = self.app.renderer.base_size(P, c)\n'
                                            '            if bs: f = round(max(P.w / bs[0], P.h / bs[1]) * 100, 2); set_prop(c, "sx", lt, f); '
                                            'set_prop(c, "sy", lt, f); set_prop(c, "x", lt, 0.0); set_prop(c, "y", lt, 0.0)\n'
                                            '        elif what == "fh": set_prop(c, "sx", lt, -prop_at(c, "sx", lt))\n'
                                            '        elif what == "fv": set_prop(c, "sy", lt, -prop_at(c, "sy", lt))\n'
                                            '        elif what == "center": set_prop(c, "x", lt, 0.0); set_prop(c, "y", lt, 0.0)\n'
                                            '        elif what == "reset":\n'
                                            '            for k in ("x", "y", "sx", "sy", "rot", "opacity"): c["props"][k] = {"v": DEFAULT_PROPS[k], '
                                            '"k": []}\n'
                                            '        self.app.on_changed(insp=False); self.refresh()\n'
                                            '    def __init__(self, app):\n'
                                            '        self._init_core(app)\n'
                                            '        self.mask_panel = MaskPanel(app)\n'
                                            '        sc = QScrollArea(); sc.setWidgetResizable(True); sc.setFrameShape(QFrame.NoFrame); '
                                            'sc.setWidget(self.mask_panel)\n'
                                            '        self._mask_tab = self.tabs.addTab(sc, "Mask")\n'
                                            '    def refresh(self, full=False):\n'
                                            '        self._refresh_core(full)\n'
                                            '        c = self.app.sel_clip()\n'
                                            '        self.tabs.setTabVisible(self._mask_tab, bool(c) and c["kind"] != "audio")\n'
                                            '        if not getattr(self, "_tab_icons", False):\n'
                                            '            self._tab_icons = True; self.tabs.setIconSize(QSize(22, 22)); '
                                            'self.tabs.tabBar().setUsesScrollButtons(False); self.tabs.tabBar().setExpanding(True); '
                                            'self.tabs.tabBar().setStyleSheet("QTabBar::tab{padding:7px 4px;min-width:20px;}")\n'
                                            '            for i, (ic, tip) in enumerate((("move", "Transform"), ("effects", "Effects"), ("text", '
                                            '"Text"), ("sound", "Audio"), ("keys", "Keyframes"), ("mask", "Mask"))):\n'
                                            '                self.tabs.setTabText(i, ""); self.tabs.setTabIcon(i, app_icon(ic)); '
                                            'self.tabs.setTabToolTip(i, tip)\n'
                                            '        self.mask_panel.load(c, force=full)\n',
